// Raymarches the sdf_scene of the WebGL2 code in the textarea (as generated by Webgl2CodeGenerator.GenerateShaderCode),
// lit by a single point light. Drag the view to orbit the camera, scroll to zoom.

const VERTEX_SHADER = `#version 300 es
in vec2 position;
void main() { gl_Position = vec4(position, 0.0, 1.0); }`;

// "#line 1" makes the line numbers in compile errors match the lines in the textarea
const fragmentShader = sdfCode => `#version 300 es
precision highp float;
precision highp int;

uniform vec2 uResolution;
uniform vec3 uCameraPosition;
uniform vec3 uCameraTarget;
uniform vec3 uLightPosition;

out vec4 fragColor;

#line 1
${sdfCode}

const int MAX_STEPS = 200;
const float MAX_DISTANCE = 100.0;
const float SURFACE_DISTANCE = 0.001;

float map(vec3 p) { return sdf_scene(p); }

float raymarch(vec3 ro, vec3 rd)
{
    float t = 0.0;
    for (int i = 0; i < MAX_STEPS; i++)
    {
        vec3 p = ro + rd * t;
        float d = map(p);
        if (d < SURFACE_DISTANCE || t > MAX_DISTANCE) break;
        t += d;
    }
    return t;
}

// Tetrahedron technique: four samples instead of six central differences
vec3 calcNormal(vec3 p)
{
    const vec2 k = vec2(1.0, -1.0);
    const float e = 0.0005;
    return normalize(
        k.xyy * map(p + k.xyy * e) +
        k.yyx * map(p + k.yyx * e) +
        k.yxy * map(p + k.yxy * e) +
        k.xxx * map(p + k.xxx * e));
}

// Marches towards the light; the closer a ray passes by other geometry, the darker the penumbra
float softShadow(vec3 ro, vec3 rd, float maxT)
{
    float result = 1.0;
    float t = 0.02;
    for (int i = 0; i < 64 && t < maxT; i++)
    {
        float d = map(ro + rd * t);
        if (d < SURFACE_DISTANCE) return 0.0;
        result = min(result, 8.0 * d / t);
        t += clamp(d, 0.01, 0.5);
    }
    return clamp(result, 0.0, 1.0);
}

float ambientOcclusion(vec3 p, vec3 n)
{
    float occlusion = 0.0;
    float weight = 1.0;
    for (int i = 1; i <= 5; i++)
    {
        float h = 0.03 * float(i);
        occlusion += (h - map(p + n * h)) * weight;
        weight *= 0.85;
    }
    return clamp(1.0 - 4.0 * occlusion, 0.0, 1.0);
}

vec3 background(vec3 rd)
{
    return mix(vec3(0.09, 0.09, 0.11), vec3(0.22, 0.24, 0.3), clamp(rd.y * 0.5 + 0.5, 0.0, 1.0));
}

void main()
{
    vec2 uv = (gl_FragCoord.xy - 0.5 * uResolution) / uResolution.y;

    vec3 forward = normalize(uCameraTarget - uCameraPosition);
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = cross(right, forward);
    vec3 ro = uCameraPosition;
    vec3 rd = normalize(uv.x * right + uv.y * up + 1.6 * forward);

    float t = raymarch(ro, rd);
    if (t > MAX_DISTANCE)
    {
        fragColor = vec4(pow(background(rd), vec3(1.0 / 2.2)), 1.0);
        return;
    }

    vec3 p = ro + rd * t;
    vec3 n = calcNormal(p);

    vec3 toLight = uLightPosition - p;
    float lightDistance = length(toLight);
    vec3 l = toLight / lightDistance;
    vec3 h = normalize(l - rd);

    float attenuation = 1.0 / (1.0 + 0.02 * lightDistance * lightDistance);
    float shadow = softShadow(p + n * 0.002, l, lightDistance);
    float diffuse = max(dot(n, l), 0.0);
    float specular = pow(max(dot(n, h), 0.0), 48.0) * diffuse;
    float occlusion = ambientOcclusion(p, n);

    vec3 albedo = vec3(0.85, 0.62, 0.42);
    vec3 lightColor = vec3(1.0, 0.95, 0.88) * 3.5;
    vec3 color = albedo * vec3(0.12, 0.13, 0.17) * occlusion
               + (albedo * diffuse + 0.5 * specular) * lightColor * attenuation * shadow;

    // Exponential tone mapping keeps bright highlights from clipping to white
    color = 1.0 - exp(-1.4 * color);

    float fog = 1.0 - exp(-0.002 * t * t);
    color = mix(color, background(rd), fog);

    fragColor = vec4(pow(color, vec3(1.0 / 2.2)), 1.0);
}`;

const codeInput = document.getElementById('code');
const canvas = document.getElementById('view');
const gl = canvas.getContext('webgl2');

const camera = { yaw: 0.7, pitch: 0.35, distance: 8, target: [0, 0, 0] };
const lightPosition = [4, 6, 3];
let program = null;

function compile(type, source) {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
        const log = gl.getShaderInfoLog(shader);
        gl.deleteShader(shader);
        throw new Error(log);
    }
    return shader;
}

function createProgram(sdfCode) {
    const vertex = compile(gl.VERTEX_SHADER, VERTEX_SHADER);
    const fragment = compile(gl.FRAGMENT_SHADER, fragmentShader(sdfCode));
    const created = gl.createProgram();
    gl.attachShader(created, vertex);
    gl.attachShader(created, fragment);
    gl.bindAttribLocation(created, 0, 'position');
    gl.linkProgram(created);
    gl.deleteShader(vertex);
    gl.deleteShader(fragment);
    if (!gl.getProgramParameter(created, gl.LINK_STATUS)) {
        const log = gl.getProgramInfoLog(created);
        gl.deleteProgram(created);
        throw new Error(log);
    }
    return created;
}

// A failing compile keeps showing the last scene that worked; the error is on the textarea's tooltip and in the console
function updateProgram() {
    try {
        const created = createProgram(codeInput.value);
        if (program) gl.deleteProgram(program);
        program = created;
        codeInput.classList.remove('error');
        codeInput.title = '';
        requestRender();
    } catch (error) {
        codeInput.classList.add('error');
        codeInput.title = error.message;
        console.error(error.message);
    }
}

function cameraPosition() {
    const { yaw, pitch, distance, target } = camera;
    return [
        target[0] + distance * Math.cos(pitch) * Math.sin(yaw),
        target[1] + distance * Math.sin(pitch),
        target[2] + distance * Math.cos(pitch) * Math.cos(yaw),
    ];
}

function resize() {
    const scale = window.devicePixelRatio || 1;
    const width = Math.round(canvas.clientWidth * scale);
    const height = Math.round(canvas.clientHeight * scale);
    if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
    }
}

function render() {
    renderRequested = false;
    resize();
    gl.viewport(0, 0, canvas.width, canvas.height);
    if (!program) return;

    gl.useProgram(program);
    gl.uniform2f(gl.getUniformLocation(program, 'uResolution'), canvas.width, canvas.height);
    gl.uniform3fv(gl.getUniformLocation(program, 'uCameraPosition'), cameraPosition());
    gl.uniform3fv(gl.getUniformLocation(program, 'uCameraTarget'), camera.target);
    gl.uniform3fv(gl.getUniformLocation(program, 'uLightPosition'), lightPosition);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
}

// Raymarching is expensive, so a frame is only drawn when something changed
let renderRequested = false;
function requestRender() {
    if (!renderRequested) {
        renderRequested = true;
        requestAnimationFrame(render);
    }
}

function setUpFullScreenTriangle() {
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
}

function setUpInput() {
    let compileTimer;
    codeInput.addEventListener('input', () => {
        clearTimeout(compileTimer);
        compileTimer = setTimeout(updateProgram, 300);
    });

    // A tab key inserts indentation instead of leaving the textarea
    codeInput.addEventListener('keydown', event => {
        if (event.key !== 'Tab') return;
        event.preventDefault();
        codeInput.setRangeText('    ', codeInput.selectionStart, codeInput.selectionEnd, 'end');
        codeInput.dispatchEvent(new Event('input'));
    });

    let dragging = null;
    canvas.addEventListener('pointerdown', event => {
        dragging = { x: event.clientX, y: event.clientY };
        canvas.setPointerCapture(event.pointerId);
    });
    canvas.addEventListener('pointermove', event => {
        if (!dragging) return;
        camera.yaw -= (event.clientX - dragging.x) * 0.01;
        camera.pitch = Math.max(-1.5, Math.min(1.5, camera.pitch + (event.clientY - dragging.y) * 0.01));
        dragging = { x: event.clientX, y: event.clientY };
        requestRender();
    });
    canvas.addEventListener('pointerup', () => dragging = null);
    canvas.addEventListener('pointercancel', () => dragging = null);

    canvas.addEventListener('wheel', event => {
        event.preventDefault();
        camera.distance = Math.max(0.5, Math.min(60, camera.distance * Math.exp(event.deltaY * 0.001)));
        requestRender();
    }, { passive: false });

    window.addEventListener('resize', requestRender);
}

if (!gl) {
    codeInput.classList.add('error');
    codeInput.title = 'This browser does not support WebGL2';
} else {
    setUpFullScreenTriangle();
    setUpInput();
    updateProgram();
}
